const uncompactedChars = `-- name: UncompactedChars :one
SELECT coalesce(sum(length(m.content::text)), 0)::bigint
FROM conversation_messages m
WHERE m.device_id = $1::uuid AND m.id > coalesce((
    SELECT c.upto_message_id FROM conversation_compactions c
    WHERE c.device_id = $1::uuid ORDER BY c.created_at DESC, c.id DESC LIMIT 1
), 0)
`

func (q *Queries) UncompactedChars(ctx context.Context, deviceID pgtype.UUID) (int64, error) {
	row := q.db.QueryRow(ctx, uncompactedChars, deviceID)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

